let products=[],orders=[],selectedProductImage=null,photoObjectUrl='';document.querySelector('.notice').textContent='Katalog, pesanan, dan foto produk terhubung ke penyimpanan Cloudflare.';
const rupiah=value=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(value);
const overviewNotice=document.querySelector('#overview .notice');if(overviewNotice)overviewNotice.textContent='Data dashboard berasal dari Cloudflare D1. Pembayaran saat ini menggunakan Midtrans Sandbox dan simulasi manual—tidak menagihkan uang nyata.';
const escapeHtml=value=>String(value).replace(/[&<>'"]/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[char]));
const toast=message=>{const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');setTimeout(()=>el.classList.remove('show'),2400)};
const statusLabel={pending:'Baru',paid:'Diproses',failed:'Dibatalkan',expired:'Kedaluwarsa',cancelled:'Dibatalkan',refunded:'Dikembalikan'},statusValue={Baru:'pending',Diproses:'paid',Dibatalkan:'cancelled',Kedaluwarsa:'expired',Dikembalikan:'refunded'},fulfillmentLabel={waiting:'Menunggu',preparing:'Disiapkan',shipped:'Dikirim',completed:'Selesai'};
async function api(path,options={}){const headers={...(options.headers||{})};if(options.body&&!(options.body instanceof FormData))headers['content-type']='application/json';const response=await fetch(path,{...options,headers}),data=await response.json().catch(()=>({}));if(response.status===401){showLogin();throw new Error('Silakan masuk kembali')}if(!response.ok)throw new Error(data.error||'Layanan belum tersedia');return data}
function showLogin(){document.querySelector('#loginScreen').classList.remove('hidden');document.querySelector('#password').value=''}
function renderProducts(){const query=document.querySelector('#productSearch').value.toLowerCase(),category=document.querySelector('#categoryFilter').value,filtered=products.filter(item=>(item.name.toLowerCase().includes(query)||item.category.toLowerCase().includes(query))&&(!category||item.category===category));document.querySelector('#productRows').innerHTML=filtered.map(item=>`<tr><td class="product-name">${escapeHtml(item.name)}</td><td>${escapeHtml(item.category)}</td><td>${rupiah(item.price)}</td><td>${item.stock}</td><td><span class="status ${item.stock<=2?'low':''}">${item.stock<=2?'Stok rendah':item.isActive?'Aktif':'Nonaktif'}</span></td><td><button class="icon-btn edit-product" data-id="${item.id}">Edit</button></td></tr>`).join('');document.querySelector('#productEmpty').hidden=filtered.length>0;document.querySelector('#productCount').textContent=products.length;document.querySelector('#lowStockCount').textContent=products.filter(item=>item.stock<=2).length;document.querySelectorAll('.edit-product').forEach(button=>button.addEventListener('click',()=>openProduct(Number(button.dataset.id))))}
function renderOrders(){const query=document.querySelector('#orderSearch').value.toLowerCase(),filter=document.querySelector('#orderFilter').value,filtered=orders.filter(order=>(order.id.toLowerCase().includes(query)||order.customer.toLowerCase().includes(query))&&(!filter||(statusLabel[order.status]||order.status)===filter));document.querySelector('#orderRows').innerHTML=filtered.length?filtered.map(order=>`<tr><td class="product-name">#${escapeHtml(order.id)}</td><td>${escapeHtml(order.customer)}</td><td>${new Date(order.createdAt).toLocaleDateString('id-ID')}</td><td>${rupiah(order.total)}</td><td><select class="filter order-status" data-id="${escapeHtml(order.id)}"><option ${(statusLabel[order.status]||order.status)==='Baru'?'selected':''}>Baru</option><option ${(statusLabel[order.status]||order.status)==='Diproses'?'selected':''}>Diproses</option><option ${(statusLabel[order.status]||order.status)==='Dibatalkan'?'selected':''}>Dibatalkan</option><option ${(statusLabel[order.status]||order.status)==='Kedaluwarsa'?'selected':''}>Kedaluwarsa</option><option ${(statusLabel[order.status]||order.status)==='Dikembalikan'?'selected':''}>Dikembalikan</option></select></td><td><span class="status">${escapeHtml(fulfillmentLabel[order.fulfillmentStatus]||'Menunggu')}</span></td><td><button class="icon-btn order-detail-btn" data-id="${escapeHtml(order.id)}">Detail</button></td></tr>`).join(''):'<tr><td colspan="7" class="empty">Belum ada pesanan nyata.</td></tr>';document.querySelectorAll('.order-status').forEach(select=>select.addEventListener('change',async()=>{const order=orders.find(item=>item.id===select.dataset.id),previous=order.status;try{order.status=statusValue[select.value];await api(`/api/orders/${encodeURIComponent(order.id)}`,{method:'PATCH',body:JSON.stringify({status:order.status})});toast('Status pesanan tersimpan di D1')}catch(error){order.status=previous;renderOrders();toast(error.message)}}));document.querySelectorAll('.order-detail-btn').forEach(button=>button.addEventListener('click',()=>openOrder(button.dataset.id)))}
async function openOrder(id){const modal=document.querySelector('#orderModal'),content=document.querySelector('#orderDetailContent');document.querySelector('#orderModalTitle').textContent=`Pesanan #${id}`;content.innerHTML='<div class="empty">Memuat detail pesanan…</div>';modal.showModal();try{const data=await api(`/api/orders/${encodeURIComponent(id)}`),order=data.order,payment=data.payment,formatDate=value=>value?new Date(value.endsWith?.('Z')?value:`${value}Z`).toLocaleString('id-ID'):'—';content.innerHTML=`<div class="order-summary-grid"><div class="order-box"><small>Pelanggan</small><strong>${escapeHtml(order.customerName)}</strong><div>${escapeHtml(order.customerPhone)}</div></div><div class="order-box order-address"><small>Alamat pengiriman</small><strong>${escapeHtml(order.shippingCity)} · ${escapeHtml(order.postalCode)}</strong><div>${escapeHtml(order.shippingAddress)}</div></div><div class="order-box"><small>Status pesanan</small><strong>${escapeHtml(statusLabel[order.status]||order.status)}</strong></div><div class="order-box"><small>Pembayaran</small><strong>${escapeHtml(payment?.method||'Belum dipilih')}</strong><div>${escapeHtml(statusLabel[payment?.status]||payment?.status||'Belum tersedia')}</div></div></div><div><strong>Barang yang dipesan</strong><div class="order-lines">${data.items.map(item=>`<div class="order-line"><span><strong>${escapeHtml(item.productName)}</strong><small>${item.quantity} × ${rupiah(item.unitPrice)}</small></span><strong>${rupiah(item.lineTotal)}</strong></div>`).join('')}</div></div><div class="order-totals"><div class="order-total-row"><span>Subtotal</span><strong>${rupiah(order.subtotal)}</strong></div><div class="order-total-row"><span>Pengiriman</span><strong>${rupiah(order.shipping)}</strong></div><div class="order-total-row"><span>Diskon</span><strong>− ${rupiah(order.discount)}</strong></div><div class="order-total-row grand"><span>Total</span><strong>${rupiah(order.total)}</strong></div></div><form id="shippingForm"><strong>Pengelolaan pengiriman</strong><div class="order-summary-grid"><div class="field"><label for="fulfillmentStatus">Status pengiriman</label><select id="fulfillmentStatus"><option value="waiting">Menunggu</option><option value="preparing">Disiapkan</option><option value="shipped">Dikirim</option><option value="completed">Selesai</option></select></div><div class="field"><label for="trackingNumber">Nomor resi</label><input id="trackingNumber" value="${escapeHtml(order.trackingNumber||'')}" placeholder="Diisi saat dikirim"></div></div><div class="field"><label for="adminNote">Catatan admin</label><textarea id="adminNote" placeholder="Catatan penyiapan atau pengiriman">${escapeHtml(order.adminNote||'')}</textarea></div><div class="form-actions"><button class="primary" type="submit">Simpan pengiriman</button></div></form><div><strong>Riwayat proses</strong><div class="timeline"><div class="timeline-row"><span class="timeline-dot"></span><div><strong>Pesanan dibuat</strong><small>${formatDate(order.createdAt)}</small></div></div>${payment?.paidAt?`<div class="timeline-row"><span class="timeline-dot"></span><div><strong>Pembayaran berhasil</strong><small>${formatDate(payment.paidAt)}</small></div></div>`:''}${order.shippedAt?`<div class="timeline-row"><span class="timeline-dot"></span><div><strong>Pesanan dikirim</strong><small>${formatDate(order.shippedAt)}${order.trackingNumber?` · ${escapeHtml(order.trackingNumber)}`:''}</small></div></div>`:''}${order.completedAt?`<div class="timeline-row"><span class="timeline-dot"></span><div><strong>Pesanan selesai</strong><small>${formatDate(order.completedAt)}</small></div></div>`:''}<div class="timeline-row"><span class="timeline-dot"></span><div><strong>Pengiriman: ${escapeHtml(fulfillmentLabel[order.fulfillmentStatus]||'Menunggu')}</strong><small>${formatDate(order.updatedAt)}</small></div></div></div></div>`;document.querySelector('#fulfillmentStatus').value=order.fulfillmentStatus||'waiting';document.querySelector('#shippingForm').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;button.textContent='Menyimpan…';try{await api(`/api/orders/${encodeURIComponent(id)}/shipping`,{method:'PATCH',body:JSON.stringify({fulfillmentStatus:document.querySelector('#fulfillmentStatus').value,trackingNumber:document.querySelector('#trackingNumber').value,adminNote:document.querySelector('#adminNote').value})});modal.close();await loadData();toast('Informasi pengiriman tersimpan')}catch(error){toast(error.message);button.disabled=false;button.textContent='Simpan pengiriman'}})}catch(error){content.innerHTML=`<div class="empty">${escapeHtml(error.message)}</div>`}}
const openOrderBase=openOrder;openOrder=async function(id){await openOrderBase(id);const content=document.querySelector('#orderDetailContent'),shippingForm=document.querySelector('#shippingForm');if(!shippingForm)return;try{const data=await api(`/api/orders/${encodeURIComponent(id)}`),order=data.order,payment=data.payment,box=document.createElement('section');box.className='refund-box';if(order.status==='refunded'||payment?.status==='refunded'){box.innerHTML='<strong>Pengembalian dana</strong><p class="refund-note success-note">Refund sudah tercatat untuk pesanan ini.</p>'}else if(order.status==='paid'&&payment?.provider==='midtrans-sandbox'){box.innerHTML='<strong>Pengembalian dana Sandbox</strong><p class="refund-note">Refund akan dikirim melalui Midtrans Sandbox. Tindakan ini tidak dapat dibatalkan.</p><div class="field"><label for="refundReason">Alasan refund</label><input id="refundReason" maxlength="255" value="Pembatalan pesanan oleh toko"></div><button class="secondary refund-button" type="button">Proses refund Sandbox</button>'}else if(order.status==='paid'){box.innerHTML='<strong>Pengembalian dana manual</strong><p class="refund-note">Metode pembayaran ini perlu dikembalikan manual kepada pelanggan. Simpan bukti transfer sebelum mengubah status menjadi Dikembalikan.</p>'}else return;shippingForm.before(box);const button=box.querySelector('.refund-button');if(button)button.addEventListener('click',async()=>{if(!confirm(`Proses refund penuh ${rupiah(order.total)} untuk pesanan #${id}?`))return;button.disabled=true;button.textContent='Memproses refund…';try{const result=await api(`/api/orders/${encodeURIComponent(id)}/refund`,{method:'POST',body:JSON.stringify({reason:document.querySelector('#refundReason').value})});toast(result.message||'Refund berhasil diproses');document.querySelector('#orderModal').close();await loadData()}catch(error){toast(error.message);button.disabled=false;button.textContent='Proses refund Sandbox'}})}catch(error){toast(error.message)}};
function renderDashboard(data){const overview=document.querySelector('#overview'),values=overview.querySelectorAll('.stats .card strong'),summary=data.summary||{};values[0].textContent=rupiah(summary.revenue||0);values[1].textContent=summary.newOrders||0;values[2].textContent=summary.productCount||0;values[3].textContent=summary.lowStock||0;const dailyMap=new Map((data.daily||[]).map(item=>[item.date,Number(item.revenue)||0])),days=Array.from({length:7},(_,index)=>{const date=new Date();date.setDate(date.getDate()-(6-index));const key=date.toISOString().slice(0,10);return{key,label:date.toLocaleDateString('id-ID',{weekday:'short'}),revenue:dailyMap.get(key)||0}}),max=Math.max(...days.map(item=>item.revenue),1);overview.querySelector('.bars').innerHTML=days.map(item=>`<div class="bar-col"><span data-value="${rupiah(item.revenue)}" style="height:${Math.max(5,item.revenue/max*100)}%;${item.revenue===max&&item.revenue?'background:var(--gold)':''}"></span>${item.label}</div>`).join('');overview.querySelector('.activity').innerHTML=(data.recentOrders||[]).length?data.recentOrders.map(order=>`<div class="activity-item"><span class="dot"></span><span>Pesanan <b>#${escapeHtml(order.id)}</b> · ${escapeHtml(statusLabel[order.status]||order.status)}</span><time>${new Date(order.createdAt.endsWith?.('Z')?order.createdAt:`${order.createdAt}Z`).toLocaleDateString('id-ID',{day:'2-digit',month:'short'})}</time></div>`).join(''):'<div class="empty">Belum ada aktivitas pesanan.</div>';overview.querySelector('.rank-list').innerHTML=data.topProducts.length?data.topProducts.map((item,index)=>`<div class="rank-item"><span class="rank">${index+1}</span><span><b>${escapeHtml(item.name)}</b><small>${item.quantity} terjual</small></span><span class="mini-total">${rupiah(item.total)}</span></div>`).join(''):'<div class="empty">Belum ada data penjualan.</div>';overview.querySelector('.stock-list').innerHTML=data.lowStock.length?data.lowStock.map(item=>`<div class="stock-row"><span><b>${escapeHtml(item.name)}</b><small>Tersisa ${item.stock} unit</small><span class="stock-meter"><span style="width:${Math.max(8,item.stock*9)}%"></span></span></span><span class="status ${item.stock<=2?'low':''}">${item.stock<=2?'Rendah':'Cukup'}</span></div>`).join(''):'<div class="empty">Stok seluruh produk masih aman.</div>'}
const renderDashboardBase=renderDashboard;renderDashboard=function(data){renderDashboardBase(data);const overview=document.querySelector('#overview'),cards=overview.querySelectorAll('.stats .card'),summary=data.summary||{};cards[0].querySelector('.trend').textContent='Pembayaran berhasil bulan berjalan';cards[1].querySelector('.trend').textContent=`${summary.newOrders||0} perlu diproses`;cards[2].querySelector('.trend').textContent='Produk tersimpan di katalog';cards[3].querySelector('.trend').textContent='Stok 2 unit atau kurang';const chartBadge=overview.querySelector('.grid .panel .panel-head .status');if(chartBadge)chartBadge.textContent='Data D1'};
async function loadData(){const[productData,orderData,dashboardData]=await Promise.all([api('/api/products?admin=1'),api('/api/orders'),api('/api/dashboard')]);products=productData.products;orders=orderData.orders;renderProducts();renderOrders();renderDashboard(dashboardData)}
function updatePhotoPreview(url=''){const preview=document.querySelector('#photoPreview'),remove=document.querySelector('#removePhoto');preview.classList.toggle('visible',Boolean(url));remove.classList.toggle('visible',Boolean(url));if(url)preview.src=url;else preview.removeAttribute('src')}
function clearSelectedPhoto(){selectedProductImage=null;if(photoObjectUrl){URL.revokeObjectURL(photoObjectUrl);photoObjectUrl=''}document.querySelector('#productImageFile').value=''}
function openProduct(id){const item=products.find(product=>product.id===id);clearSelectedPhoto();document.querySelector('#modalTitle').textContent=item?'Edit produk':'Tambah produk';document.querySelector('#productId').value=item?.id||'';document.querySelector('#productName').value=item?.name||'';document.querySelector('#productCategory').value=item?.category||'Sofa';document.querySelector('#productMaterial').value=item?.material||'';document.querySelector('#productPrice').value=item?.price||'';document.querySelector('#productStock').value=item?.stock??'';document.querySelector('#productDimensions').value=item?.dimensions||'';document.querySelector('#productDescription').value=item?.description||'';document.querySelector('#productImageUrl').value=item?.imageUrl||'';document.querySelector('#photoName').textContent=item?.imageUrl?'Foto produk saat ini':'Belum ada foto dipilih';document.querySelector('#productStatus').value=item?.isActive?'Aktif':item?'Nonaktif':'Aktif';updatePhotoPreview(item?.imageUrl||'');document.querySelector('#productModal').showModal()}
async function uploadProductImage(file){const form=new FormData();form.append('image',file);const result=await api('/api/uploads/product-image',{method:'POST',body:form});return result.imageUrl}
document.querySelector('#loginForm').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;button.textContent='Memeriksa…';try{await api('/api/session',{method:'POST',body:JSON.stringify({password:document.querySelector('#password').value})});document.querySelector('#loginScreen').classList.add('hidden');toast('Login berhasil');await loadData()}catch(error){toast(error.message)}finally{button.disabled=false;button.textContent='Masuk ke dashboard'}});
const profileButton=document.querySelector('#profileBtn'),profileMenu=document.querySelector('#profileMenu'),backupButton=document.createElement('button');backupButton.id='backupBtn';backupButton.textContent='Unduh cadangan data';profileMenu.insertBefore(backupButton,document.querySelector('#logoutBtn'));profileButton.addEventListener('click',()=>{const open=profileMenu.hidden;profileMenu.hidden=!open;profileButton.setAttribute('aria-expanded',String(open))});document.addEventListener('click',event=>{if(!event.target.closest('.top-actions')){profileMenu.hidden=true;profileButton.setAttribute('aria-expanded','false')}});backupButton.addEventListener('click',async()=>{backupButton.disabled=true;backupButton.textContent='Menyiapkan…';try{const response=await fetch('/api/admin/export');if(response.status===401){showLogin();throw new Error('Silakan masuk kembali')}if(!response.ok)throw new Error('Cadangan belum dapat dibuat');const blob=await response.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=`ruangrupa-backup-${new Date().toISOString().slice(0,10)}.json`;document.body.append(link);link.click();link.remove();URL.revokeObjectURL(url);profileMenu.hidden=true;toast('Cadangan data berhasil dibuat')}catch(error){toast(error.message)}finally{backupButton.disabled=false;backupButton.textContent='Unduh cadangan data'}});document.querySelector('#logoutBtn').addEventListener('click',async()=>{await fetch('/api/session',{method:'DELETE'});profileMenu.hidden=true;showLogin()});
document.querySelectorAll('.menu button').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.menu button,.view').forEach(el=>el.classList.remove('active'));button.classList.add('active');document.querySelector(`#${button.dataset.view}`).classList.add('active');const labels={overview:['Selamat datang.','Ringkasan toko RuangRupa hari ini.'],products:['Produk','Kelola katalog toko Anda.'],orders:['Pesanan','Pantau pemenuhan pesanan pelanggan.'],customers:['Pelanggan','Kenali pelanggan RuangRupa.'],promo:['Promosi','Kelola penawaran toko.']};document.querySelector('#pageTitle').textContent=labels[button.dataset.view][0];document.querySelector('#pageSubtitle').textContent=labels[button.dataset.view][1]}));document.querySelectorAll('[data-jump]').forEach(button=>button.addEventListener('click',()=>document.querySelector(`.menu button[data-view="${button.dataset.jump}"]`).click()));
document.querySelector('#addProduct').addEventListener('click',()=>openProduct());document.querySelector('#closeModal').addEventListener('click',()=>document.querySelector('#productModal').close());document.querySelector('#cancelModal').addEventListener('click',()=>document.querySelector('#productModal').close());document.querySelector('#productImageFile').addEventListener('change',event=>{const file=event.target.files[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){event.target.value='';toast('Pilih foto JPG, PNG, atau WebP');return}selectedProductImage=file;if(photoObjectUrl)URL.revokeObjectURL(photoObjectUrl);photoObjectUrl=URL.createObjectURL(file);document.querySelector('#photoName').textContent=file.name;updatePhotoPreview(photoObjectUrl)});document.querySelector('#removePhoto').addEventListener('click',()=>{clearSelectedPhoto();document.querySelector('#productImageUrl').value='';document.querySelector('#photoName').textContent='Belum ada foto dipilih';updatePhotoPreview('')});document.querySelector('#photoPreview').addEventListener('error',()=>document.querySelector('#photoPreview').classList.remove('visible'));document.querySelector('#productForm').addEventListener('submit',async event=>{event.preventDefault();const id=Number(document.querySelector('#productId').value),button=document.querySelector('#saveProduct');button.disabled=true;button.textContent=selectedProductImage?'Mengunggah foto…':'Menyimpan…';try{let imageUrl=document.querySelector('#productImageUrl').value.trim();if(selectedProductImage)imageUrl=await uploadProductImage(selectedProductImage);button.textContent='Menyimpan…';const data={name:document.querySelector('#productName').value.trim(),category:document.querySelector('#productCategory').value,material:document.querySelector('#productMaterial').value.trim(),price:Number(document.querySelector('#productPrice').value),stock:Number(document.querySelector('#productStock').value),dimensions:document.querySelector('#productDimensions').value.trim(),description:document.querySelector('#productDescription').value.trim(),imageUrl,status:document.querySelector('#productStatus').value};await api(id?`/api/products/${id}`:'/api/products',{method:id?'PATCH':'POST',body:JSON.stringify(data)});clearSelectedPhoto();document.querySelector('#productModal').close();await loadData();toast(id?'Produk dan foto berhasil disimpan':'Produk dan foto berhasil ditambahkan')}catch(error){toast(error.message)}finally{button.disabled=false;button.textContent='Simpan produk'}});
document.querySelector('#closeOrderModal').addEventListener('click',()=>document.querySelector('#orderModal').close());document.querySelector('#orderModal').addEventListener('click',event=>{if(event.target===event.currentTarget)event.currentTarget.close()});
document.querySelector('#productSearch').addEventListener('input',renderProducts);document.querySelector('#categoryFilter').addEventListener('change',renderProducts);document.querySelector('#orderSearch').addEventListener('input',renderOrders);document.querySelector('#orderFilter').addEventListener('change',renderOrders);
(async()=>{try{const session=await api('/api/session');if(session.authenticated){document.querySelector('#loginScreen').classList.add('hidden');await loadData()}else showLogin()}catch(error){showLogin();toast('Backend belum tersedia')}})();for(const source of ['admin-settings.js','admin-reports.js']){const script=document.createElement('script');script.src=`${source}?v=35`;document.body.append(script)}if('serviceWorker'in navigator&&location.protocol!=='file:')window.addEventListener('load',()=>navigator.serviceWorker.register('./sw.js'));
